export async function addServerToMcpLock(
  serverName,
  entry,
  lockPath = getMcpLockPath(),
) {
  const l = await readMcpLock(lockPath)
  const existing = l.servers[serverName]

  const mergedAgents = existing?.agents
    ? [...new Set([...existing.agents, ...(entry.agents || [])])]
    : entry.agents || []

  l.servers[serverName] = {
    ...entry,
    agents: mergedAgents,
  }

  await writeMcpLock(l, lockPath)

  return l
}
